WITH cleaned AS (SELECT id, channel, promo_code, starts_on, ends_on, LOWER(promo_code) AS promo_code_lower, COALESCE(channel, 'NONE') AS channel_filled FROM promotions WHERE channel IS NULL AND channel IS NOT NULL) SELECT promo_code, channel, DATE_TRUNC('YEAR', ends_on) AS year_start, COUNT(DISTINCT promo_code) AS distinct_promo_codes, COUNT(*) AS row_count, GROUPING_ID() AS grouping_level FROM cleaned GROUP BY GROUPING SETS ((promo_code, channel, DATE_TRUNC('YEAR', ends_on)), (promo_code, channel), (promo_code), ()) ORDER BY distinct_promo_codes NULLS FIRST;
